          createdAt: Date.parse(shareItem.share.createdAt),
          modifiedAt: Date.parse(shareItem.share.createdAt),
        }).finally(() => navigateToRoot());
      }
    }
  }
}, [currentView, currentShareId, sharedItems, downloadSharedFile, navigateToRoot]);

